import { Checkout } from './Checkout';

// Mock contexts - the silent sentinels
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();
const mockCart = { items: [{ id: '1', name: 'Item', price: 99.99 }], total: 99.99 };

